import{_ as p,W as n,s as o,u as d,I as e,ah as u,w as i,Z as t,A as l}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const f=JSON.parse('{"title":"Vim-plug：极简 Vim 插件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"Vim-plug：极简 Vim 插件管理器 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim-plug：极简 Vim 插件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim-plug：极简 Vim 插件管理器 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager","title":"Vim-plug：极简 Vim 插件管理器","tag":"201806"},"relativePath":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md","filePath":"[post].md"}'),g={name:"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md"};function m(r,a,h,c,v,b){const s=n("Link");return d(),o("div",null,[a[20]||(a[20]=e("h1",{id:"vim-plug-极简-vim-插件管理器",tabindex:"-1"},[i("Vim-plug：极简 Vim 插件管理器 "),e("a",{class:"header-anchor",href:"#vim-plug-极简-vim-插件管理器","aria-label":"Permalink to Vim-plug：极简 Vim 插件管理器"},"​")],-1)),a[21]||(a[21]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/06/vim-plug-720x340.png",alt:""})],-1)),e("p",null,[a[1]||(a[1]=i("当没有插件管理器时，Vim 用户必须手动下载 tarball 包形式的插件，并将它们解压到 ")),a[2]||(a[2]=e("code",null,"~/.vim",-1)),a[3]||(a[3]=i(" 目录中。在少量插件的时候可以。但当他们安装更多的插件时，就会变得一团糟。所有插件文件分散在单个目录中，用户无法找到哪个文件属于哪个插件。此外，他们无法找到他们应该删除哪个文件来卸载插件。这时 Vim 插件管理器就可以派上用场。插件管理器将安装插件的文件保存在单独的目录中，因此管理所有插件变得非常容易。我们几个月前已经写了关于 ")),t(s,{href:"https://linux.cn/article-9416-1.html"},{default:l(()=>a[0]||(a[0]=[i("Vundle")])),_:1}),a[4]||(a[4]=i(" 的文章。今天，我们将看到又一个名为 “Vim-plug” 的 Vim 插件管理器。"))]),a[22]||(a[22]=u(`<p>Vim-plug 是一个自由、开源、速度非常快的、极简的 vim 插件管理器。它可以并行地安装或更新插件。你还可以回滚更新。它创建<ruby>浅层克隆<rt>shallow clone</rt></ruby>最小化磁盘空间使用和下载时间。它支持按需加载插件以加快启动时间。其他值得注意的特性是支持分支/标签/提交、post-update 钩子、支持外部管理的插件等。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to 安装">​</a></h3><p>安装和使用起来非常容易。你只需打开终端并运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ curl -fLo ~/.vim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><p>Neovim 用户可以使用以下命令安装 Vim-plug：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ curl -fLo ~/.config/nvim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to 用法">​</a></h3><h4 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to 安装插件">​</a></h4><p>要安装插件，你必须如下所示首先在 Vim 配置文件中声明它们。一般 Vim 的配置文件是 <code>~/.vimrc</code>，Neovim 的配置文件是 <code>~/.config/nvim/init.vim</code>。请记住，当你在配置文件中声明插件时，列表应该以 <code>call plug#begin(PLUGIN_DIRECTORY)</code> 开始，并以 <code>plug#end()</code> 结束。</p><p>例如，我们安装 “lightline.vim” 插件。为此，请在 <code>~/.vimrc</code> 的顶部添加以下行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call plug#begin(&#39;~/.vim/plugged&#39;)</span></span>
<span class="line"><span>Plug &#39;itchyny/lightline.vim&#39;</span></span>
<span class="line"><span>call plug#end()</span></span></code></pre></div><p>在 vim 配置文件中添加上面的行后，通过输入以下命令重新加载：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:source ~/.vimrc</span></span></code></pre></div><p>或者，只需重新加载 Vim 编辑器。</p><p>现在，打开 vim 编辑器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vim</span></span></code></pre></div><p>使用以下命令检查状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:PlugStatus</span></span></code></pre></div><p>然后输入下面的命令，然后按回车键安装之前在配置文件中声明的插件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:PlugInstall</span></span></code></pre></div><h4 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to 更新插件">​</a></h4><p>要更新插件，请运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:PlugUpdate</span></span></code></pre></div><p>更新插件后，按下 <code>d</code> 查看更改。或者，你可以之后输入 <code>:PlugDiff</code>。</p><h4 id="审查插件" tabindex="-1">审查插件 <a class="header-anchor" href="#审查插件" aria-label="Permalink to 审查插件">​</a></h4><p>有时，更新的插件可能有新的 bug 或无法正常工作。要解决这个问题，你可以简单地回滚有问题的插件。输入 <code>:PlugDiff</code> 命令，然后按回车键查看上次 <code>:PlugUpdate</code>的更改，并在每个段落上按 <code>X</code> 将每个插件回滚到更新前的前一个状态。</p><h4 id="删除插件" tabindex="-1">删除插件 <a class="header-anchor" href="#删除插件" aria-label="Permalink to 删除插件">​</a></h4><p>删除一个插件删除或注释掉你以前在你的 vim 配置文件中添加的 <code>plug</code> 命令。然后，运行 <code>:source ~/.vimrc</code> 或重启 Vim 编辑器。最后，运行以下命令卸载插件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:PlugClean</span></span></code></pre></div><p>该命令将删除 vim 配置文件中所有未声明的插件。</p><h4 id="升级-vim-plug" tabindex="-1">升级 Vim-plug <a class="header-anchor" href="#升级-vim-plug" aria-label="Permalink to 升级 Vim-plug">​</a></h4><p>要升级vim-plug本身，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:PlugUpgrade</span></span></code></pre></div><p>如你所见，使用 Vim-plug 管理插件并不难。它简化了插件管理。现在去找出你最喜欢的插件并使用 Vim-plug 来安装它们。</p><p>就是这些了。我将很快在这里发布另一个有趣的话题。在此之前，请继续关注我们。</p><p>干杯!</p><hr>`,37)),e("p",null,[a[6]||(a[6]=i("via: ")),t(s,{href:"https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/"},{default:l(()=>a[5]||(a[5]=[i("https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/")])),_:1})]),e("p",null,[a[11]||(a[11]=i("作者：")),t(s,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>a[7]||(a[7]=[i("SK")])),_:1}),a[12]||(a[12]=i(" 选题：")),t(s,{href:"https://github.com/lujun9972"},{default:l(()=>a[8]||(a[8]=[i("lujun9972")])),_:1}),a[13]||(a[13]=i(" 译者：")),t(s,{href:"https://github.com/geekpi"},{default:l(()=>a[9]||(a[9]=[i("geekpi")])),_:1}),a[14]||(a[14]=i(" 校对：")),t(s,{href:"https://github.com/wxy"},{default:l(()=>a[10]||(a[10]=[i("wxy")])),_:1})]),e("p",null,[a[17]||(a[17]=i("本文由 ")),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>a[15]||(a[15]=[i("LCTT")])),_:1}),a[18]||(a[18]=i(" 原创编译，")),t(s,{href:"https://linux.cn/"},{default:l(()=>a[16]||(a[16]=[i("Linux中国")])),_:1}),a[19]||(a[19]=i(" 荣誉推出"))])])}const C=p(g,[["render",m]]);export{f as __pageData,C as default};
